"""Acceptance refinement; includes all seven Nov12 functional cases. Fixture data only."""
import importlib.util,json,os
from pathlib import Path
spec=importlib.util.spec_from_file_location('baseline',Path(__file__).with_name('qa-20261112.py'));base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
OUT=Path('var/acceptance-refinement');OUT.mkdir(parents=True,exist_ok=True)
class Acceptance(base.Remediation):
 def resource(self,label):self.page.locator('#athlete-resource-nav').get_by_role('link',name=label,exact=True).click()
 def test_08_parent_destinations_and_five_tactical_tabs(self):
  original=self.state();self.page.goto(base.BASE+'/my-pathway?view=family');nav=self.page.locator('#parent-workspace-nav');nav.wait_for();self.assertEqual(nav.locator('a').all_text_contents(),['Players','Recruiting','Network/Messaging','Discover','Calendar','Saved']);self.page.evaluate('document.activeElement?.blur()');self.page.screenshot(path=str(OUT/f'{base.ENGINE}-ipad-parent.png'),full_page=True);self.page.screenshot(path=str(OUT/f'{base.ENGINE}-ipad-parent-viewport.png'))
  nav.get_by_role('link',name='Saved',exact=True).click();self.assertTrue(self.page.locator('#family-saved').is_visible());nav.get_by_role('link',name='Players',exact=True).click();self.page.locator('.family-athlete-card').get_by_role('link',name='View Athlete').click();self.page.wait_for_selector('#show-tryouts');self.assertEqual(self.page.locator('#profile-nav a').all_text_contents(),['Profile','Schedule','Stats','Media','Recruiting']);self.assertEqual(self.page.locator('#athlete-resource-nav a').all_text_contents(),['My Feed','Development','Community','Network']);self.assertEqual(self.state(),original)
  self.page.screenshot(path=str(OUT/f'{base.ENGINE}-ipad-athlete.png'),full_page=True);self.page.screenshot(path=str(OUT/f'{base.ENGINE}-ipad-athlete-viewport.png'));self.section('Recruiting');self.page.wait_for_selector('#optional-recruiting');self.assertNotIn('recruiting',self.state()['profiles'][0]['modules']);self.assertEqual(self.page.locator('#profile-nav [aria-current=page]').inner_text(),'Recruiting');self.section('Profile');self.page.wait_for_selector('#show-tryouts');self.assertEqual(self.state(),original)
  destinations=[('Calendar','#platform-calendar'),('Network/Messaging','.ap-message'),('Discover','#sports'),('Recruiting','[aria-label="Recruiting research"]')]
  for label,target in destinations:
   self.page.goto(base.BASE+'/my-pathway?view=family');self.page.locator('#parent-workspace-nav').get_by_role('link',name=label,exact=True).click();self.page.wait_for_selector(target)
  self.assertEqual(self.state(),original)
 def test_09_feed_source_filter_reload_and_athlete_isolation(self):
  self.resource('My Feed');choices=self.page.locator('#content-choices-news');choices.wait_for();choices.evaluate('(e)=>e.open=true');enabled=choices.locator('input:not([disabled])');self.assertGreaterEqual(enabled.count(),2);self.assertEqual(self.page.locator('#my-feed .content-items article').count(),0);enabled.nth(0).check();enabled.nth(1).check();self.assertEqual(self.page.locator('#my-feed .content-items article').count(),2)
  selected=self.state()['profiles'][0]['contentSubscriptions'];self.assertEqual(len(selected),2);self.page.get_by_label('My Feed source',exact=True).select_option(selected[0]);self.assertEqual(self.page.locator('#my-feed .content-items article').count(),1);self.page.reload();self.page.wait_for_selector('#my-feed .content-items article');self.assertEqual(self.page.locator('#my-feed .content-items article').count(),2);self.page.screenshot(path=str(OUT/f'{base.ENGINE}-ipad-feed.png'),full_page=True)
  self.page.goto(base.BASE+'/build?new=1');self.page.wait_for_selector('#athlete-basics:not([disabled])');self.page.locator('#nickname').fill('Other content athlete');self.page.get_by_role('button',name='Save athlete profile').click();self.page.wait_for_selector('#show-tryouts');self.resource('My Feed');self.page.wait_for_selector('#my-feed [data-content-library]');self.assertEqual(self.page.locator('#my-feed .content-items article').count(),0);self.assertEqual(self.state()['profiles'][0]['contentSubscriptions'],selected);self.assertNotIn('recruiting',self.state()['profiles'][1]['modules'])
 def test_10_development_has_verified_free_items_for_each_sport(self):
  for sport in ['basketball','volleyball','swimming','lacrosse']:
   self.page.goto(base.BASE+'/build');self.page.wait_for_selector('#athlete-basics:not([disabled])');self.page.locator('#sport').select_option(sport);self.page.get_by_role('button',name='Save athlete profile').click();self.page.wait_for_selector('#show-tryouts');self.resource('Development');choices=self.page.locator('#content-choices-development');choices.wait_for();choices.evaluate('(e)=>e.open=true');self.assertEqual(choices.locator('input').count(),5);enabled=choices.locator('input:not([disabled])');self.assertGreaterEqual(enabled.count(),1);enabled.first.check();self.assertGreaterEqual(self.page.locator('#camps .content-items article').count(),1);self.assertEqual(self.state()['active'],self.athlete);self.assertNotIn('recruiting',self.state()['profiles'][0]['modules']);self.page.screenshot(path=str(OUT/f'{base.ENGINE}-ipad-development-{sport}.png'),full_page=True)
 def test_11_delayed_content_response_does_not_cross_athlete_boundary(self):
  value=self.state();first=value['profiles'][0];first['contentSubscriptions']=['lacrosse:news:World Lacrosse'];first['modules'].append('recruiting');first['ageYears']=16;first['ageReviewedAt']=self.page.evaluate('new Date().toISOString()');first['recruiting']['rulesReview']={'sport':'lacrosse','acknowledged':True,'at':first['ageReviewedAt']};other=json.loads(json.dumps(first));other['id']='other-stable-id';other['nickname']='Second athlete';other['contentSubscriptions']=[];other['ageYears']=15;value['profiles'].append(other);self.page.evaluate('(v)=>localStorage.setItem("arenaPathway.v2",JSON.stringify(v))',value)
  pending=[];self.page.route('**/api/reviewed-content',lambda route:pending.append(route));self.page.reload();self.page.wait_for_selector('#show-tryouts')
  for _ in range(30):
   if pending:break
   self.page.wait_for_timeout(100)
  self.assertTrue(pending);self.page.locator('#profile-select').select_option(other['id']);self.resource('My Feed');pending[0].fulfill(status=200,content_type='application/json',body=Path('data/content-review.json').read_text());self.page.wait_for_selector('#my-feed [data-content-library]');self.assertEqual(self.page.locator('#my-feed .content-items article').count(),0);self.assertEqual(self.page.locator('#my-feed input:checked').count(),0);self.assertEqual(self.state()['active'],other['id']);self.assertEqual(self.state()['profiles'][0]['contentSubscriptions'],first['contentSubscriptions']);self.page.locator('#optional-recruiting').evaluate('(e)=>e.open=true');self.page.get_by_text('Parent-controlled recruiting preview',exact=True).click();self.assertEqual(self.page.get_by_role('button',name='Parent approve local preview').count(),1);self.assertTrue(self.page.get_by_role('button',name='Parent approve local preview').is_disabled())
